package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"

	"github.com/avro/go-avro"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run <program> <source_file> <struct_name>")
		os.Exit(1)
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	err := readStructDefinition(sourceFile, structName)
	if err != nil {
		fmt.Printf("Error reading struct definition: %v\n", err)
		return
	}

	// Generate Avro schema
	schema, err := avro.GenerateSchemaFromFile(filepath.Join(sourceFile, "schema.go"))
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
		return
	}

	fmt.Println(schema)
}

func readStructDefinition(filePath string, structName string) error {
	file, err := os.Open(filePath)
	if err != nil {
		return fmt.Errorf("failed to open file: %w", err)
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := scanner.Text()
		if line == `type = "{`+structName+"}"` {
			return fmt.Errorf("struct definition not found")
		}
	}

	if err := scanner.Err(); err != nil {
		return fmt.Errorf("scanner failed: %w", err)
	}

	return nil
}
```

